function update(dt){state.time+=dt;if(state.toastTimer>0){state.toastTimer-=dt;if(state.toastTimer<=0)ui.toast.classList.remove('show')}if(!state.started||state.won)return;state.attack=Math.max(0,state.attack-dt);state.attackCd=Math.max(0,state.attackCd-dt);player.invuln=Math.max(0,player.invuln-dt);player.flap=Math.max(0,player.flap-dt);state.shake=Math.max(0,state.shake-dt);let left=keys.has('ArrowLeft')||keys.has('KeyA'),right=keys.has('ArrowRight')||keys.has('KeyD'),dir=(right?1:0)-(left?1:0),speed=[1.55,1.08,1.65,1.35,1.45][state.form];if(dir){player.face=dir;player.vx+=dir*(player.onGround?.55:.31);player.vx=clamp(player.vx,-speed,speed)}else player.vx*=player.onGround?.72:.94;if(player.jumpBuffer>0){player.jumpBuffer-=dt;if(player.onGround||player.coyote>0){player.vy=state.form===3?-6.65:state.form===1?-5.2:-5.75;player.onGround=false;player.coyote=0;player.jumpBuffer=0}}if(state.form===4&&player.flap>0&&keys.has('Space'))player.vy=Math.max(player.vy,-1.35);player.onGround=false;player.vy=Math.min(player.vy+ (state.form===4?.17:.31),state.form===4?3:6.5);moveAxis('x',player.vx);moveAxis('y',player.vy);player.x=clamp(player.x,0,worldW-player.w);if(player.onGround)player.coyote=.11;else player.coyote=Math.max(0,player.coyote-dt);if(player.y>H+55){damage();player.x=checkpoints[state.checkpoint].x;player.y=checkpoints[state.checkpoint].y;player.vy=0}
for(const b of barriers){if(b.broken||!overlapping(player,b))continue;if(state.attack>0&&((b.type==='stone'&&state.form===1)||(b.type==='roots'&&state.form===2))){b.broken=true;state.shake=.15;toast(b.type==='stone'?'Cracked stone!':'The wild roots give way.');for(let i=0;i<10;i++)state.particles.push({x:b.x+b.w/2,y:b.y+b.h/2,vx:(rnd(i+state.time)*2-1)*1.8,vy:-rnd(i+state.time+22)*2,c:b.type==='stone'?'#aca48a':'#738a52',life:.6})}else if(state.attack>0&&b.type==='stone'&&state.form!==1){player.vx=-player.face*1.6;state.attack=0;toast('Stone yields only to the bear.')}}
for(const e of enemies){if(e.hp<=0)continue;e.x+=e.dir*.43;if(e.x<e.lo)e.dir=1;if(e.x>e.hi)e.dir=-1;const box={x:e.x,y:e.y,w:15,h:13};if(overlapping(player,box)){if(state.attack>0&&player.y+player.h<box.y+10){e.hp--;player.vy=-3;state.attack=0;toast(e.hp?'A brambleling staggers!':'Brambleling scattered!')}else damage()}}
for(const s of seeds){if(!s.taken&&Math.abs(player.x+player.w/2-s.x)<14&&Math.abs(player.y+player.h/2-s.y)<25){s.taken=true;state.seeds++;ui.seeds.textContent=`✦ ${state.seeds} / 3`;toast(state.seeds===3?'All spirit seeds gathered. Find the heart-tree!':'Spirit seed recovered!');for(let i=0;i<12;i++)state.particles.push({x:s.x,y:s.y,vx:(rnd(i+state.time)*2-1)*1.3,vy:-rnd(i+state.time+33)*1.8,c:'#f3d87c',life:.7})}}
for(let i=checkpoints.length-1;i>=0;i--)if(player.x>checkpoints[i].x-16)state.checkpoint=i;
for(let i=state.particles.length-1;i>=0;i--){let p=state.particles[i];p.x+=p.vx;p.y+=p.vy;p.vy+=.07;p.life-=dt;if(p.life<=0)state.particles.splice(i,1)}
if(player.x>exit.x&&state.seeds>=3){state.won=true;toast('The Fourfold Heart blooms!');setTimeout(()=>{ui.overlay.innerHTML='<div class="card"><div class="eyebrow">THE GROVE REMEMBERS</div><h1>WILDROOT</h1><p>You restored the Fourfold Heart. The old forest stirs beneath the moon, and every creature finds its way home.</p><div class="forms"><span>🐻</span><span>🐗</span><span>🐐</span><span>🦅</span></div><button class="startbtn" id="again">WANDER AGAIN</button></div>';ui.overlay.classList.remove('hidden');document.getElementById('again').onclick=()=>location.reload()},650)}else if(player.x>exit.x)ui.hint.textContent='The heart-tree is quiet. Gather all three spirit seeds first.';else if(player.x>2200)ui.hint.textContent='The heart-tree waits beyond the moonlit ridge.';else if(player.x>1250)ui.hint.textContent='A forest altar stirs here. Find the second spirit seed.';else ui.hint.textContent='Find three spirit seeds. Bear breaks stone · Boar breaks roots · Eagle glides.';
state.camera=clamp(player.x-W*.36,0,worldW-W)}
function drawSky(){let g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#1d3542');g.addColorStop(.58,'#36545a');g.addColorStop(1,'#69745b');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.fillStyle='#efe2b3';ctx.beginPath();ctx.arc(399-state.camera*.015,53,15,0,Math.PI*2);ctx.fill();ctx.fillStyle='#30474b';ctx.beginPath();ctx.arc(405-state.camera*.015,49,14,0,Math.PI*2);ctx.fill();for(let layer=0;layer<3;layer++){let base=161+layer*20,par=state.camera*(.13+layer*.13);ctx.fillStyle=['#36545a','#2e494b','#283f40'][layer];ctx.beginPath();ctx.moveTo(0,H);for(let x=0;x<=W+10;x+=12){let wx=x+par;let y=base-Math.sin(wx*.012+layer)*13-Math.sin(wx*.025)*6;ctx.lineTo(x,y)}ctx.lineTo(W,H);ctx.fill()}for(let i=0;i<47;i++){let wx=i*103,screen=wx-state.camera*.4;if(screen< -20||screen>W+20)continue;let y=164+Math.sin(wx*.06)*13;rect(screen,y-25,5,39,'#243b37');rect(screen-7,y-31,19,10,i%3?'#3e5b46':'#496248');rect(screen-3,y-38,14,9,'#49674e');}}
function drawGround(){for(const p of platforms){let x=p.x-state.camera;if(x+p.w<0||x>W)continue;rect(x,p.y,p.w,p.h,'#4e4938');rect(x,p.y,p.w,5,'#83a166');rect(x,p.y+5,p.w,2,'#b49a5e');for(let n=0;n<Math.ceil(p.w/17);n++){let xx=x+n*17+2;rect(xx,p.y+10,5,2,'#6d6045');rect(xx+6,p.y+20,3,2,'#5d553e')}}for(const p of platforms){let x=p.x-state.camera;if(x+p.w<0||x>W||p.y>=222)continue;rect(x,p.y,p.w,3,'#9baf71');rect(x+5,p.y+5,p.w-10,2,'#647853')}}
function drawProps(){for(let i=0;i<13;i++){let wx=i*271+120,x=wx-state.camera;if(x<-20||x>W+20)continue;let y=platforms.find(p=>wx>=p.x&&wx<=p.x+p.w&&p.y>=200)?.y||222;rect(x,y-12,4,12,'#273b32');rect(x-4,y-15,12,4,i%2?'#9d6050':'#daa76b');rect(x-2,y-19,4,4,'#e3cf83')}for(const b of barriers){if(b.broken)continue;let x=b.x-state.camera;if(x<-50||x>W+50)continue;if(b.type==='stone'){rect(x,b.y,b.w,b.h,'#79796b');rect(x+3,b.y+3,b.w-6,5,'#aaa28a');rect(x+6,b.y+12,3,3,'#555d53');rect(x+b.w-9,b.y+21,4,3,'#555d53')}else{rect(x,b.y+8,b.w,b.h-8,'#465b39');for(let n=0;n<4;n++){let px=x+n*10;rect(px,b.y+4,4,13,'#738451');rect(px+4,b.y,3,8,'#a4a65d')}}}for(let i=0;i<checkpoints.length;i++){let x=checkpoints[i].x-state.camera;if(x<-20||x>W+20)continue;rect(x,183,3,39,'#594e3c');rect(x-5,183,13,10,i<=state.checkpoint?'#c9b56b':'#6d6750');if(i<=state.checkpoint){rect(x,183,3,8,'#f1d984');rect(x-3,175,8,2,'#e5d38e')}}}
function drawCollectibles(){for(const s of seeds){if(s.taken)continue;let x=s.x-state.camera,y=s.y+Math.sin(state.time*3+s.x)*3;rect(x-2,y-7,4,14,'#e6c45f');rect(x-5,y-3,10,5,'#f4e39a');rect(x-2,y-10,4,3,'#f8efc5');rect(x-1,y-2,2,2,'#fff6d8')}if(state.seeds>=3){let x=exit.x-state.camera;rect(x+4,171,24,51,'#443a2d');rect(x,166,32,12,'#958a55');rect(x+7,176,18,44,'#314437');rect(x+9,181,14,36,'#172a27');for(let n=0;n<5;n++){let a=state.time*1.6+n*Math.PI*2/5;let px=x+16+Math.cos(a)*13,py=176+Math.sin(a)*8;rect(px,py,3,3,'#f0d978')}}}
function drawEnemy(e){if(e.hp<=0)return;let x=Math.round(e.x-state.camera),y=e.y;rect(x+3,y,10,8,'#614e48');rect(x+1,y+4,14,7,'#c48167');rect(x+2,y+2,3,4,'#3f3933');rect(x+10,y+2,3,4,'#3f3933');rect(x+4,y+5,2,2,'#f0d27d');rect(x+10,y+5,2,2,'#f0d27d');rect(x+3,y+10,3,3,'#55433a');rect(x+10,y+10,3,3,'#55433a')}
function drawPlayer(){let x=Math.round(player.x-state.camera),y=Math.round(player.y),c=colors[forms[state.form]];if(player.invuln>0&&Math.floor(state.time*14)%2)return;let bob=player.onGround&&Math.abs(player.vx)>.4?Math.sin(state.time*17)*1.5:0;y=Math.round(y+bob);ctx.save();if(player.face<0){ctx.translate(x*2+player.w,0);ctx.scale(-1,1);x=0}else x=x;
if(state.form===0){rect(x+3,y+8,7,10,'#4f7650');rect(x+4,y+1,7,8,'#c5a77c');rect(x+8,y+3,4,2,'#332f2c');rect(x+2,y,9,3,'#416343');rect(x,y+3,4,2,'#416343');rect(x+4,y+18,2,3,'#533f34');rect(x+9,y+18,2,3,'#533f34');rect(x+4,y+10,2,4,'#a6c379');rect(x+11,y+10,2,4,'#a6c379');rect(x+2,y+6,3,2,'#bf965f')}
else if(state.form===1){rect(x+1,y+7,12,11,c);rect(x+3,y+2,8,7,c);rect(x+3,y,3,4,'#986846');rect(x+9,y,3,4,'#986846');rect(x+10,y+5,3,2,'#272c26');rect(x+3,y+17,3,4,'#674b3c');rect(x+9,y+17,3,4,'#674b3c');rect(x+1,y+9,3,6,'#936944')}
else if(state.form===2){rect(x,y+10,14,8,c);rect(x+8,y+5,7,8,c);rect(x+12,y+8,5,3,'#b66b50');rect(x+2,y+17,3,4,'#744a3d');rect(x+9,y+17,3,4,'#744a3d');rect(x+2,y+7,4,5,'#bd7350');rect(x+10,y+7,2,2,'#312c29')}
else if(state.form===3){rect(x+3,y+7,8,11,c);rect(x+4,y+2,8,7,c);rect(x+4,y,2,5,'#897d5c');rect(x+10,y,2,5,'#897d5c');rect(x+10,y+5,3,2,'#292d29');rect(x+3,y+17,3,4,'#776b50');rect(x+9,y+17,3,4,'#776b50');rect(x+1,y+11,3,4,'#c3b487')}
else {rect(x+4,y+5,7,10,c);rect(x+5,y+1,6,6,'#e4d7ae');rect(x+10,y+3,4,2,'#33332c');rect(x,y+6,6,7,'#a4d5d4');rect(x+10,y+6,6,7,'#5d9298');if(player.flap>0){rect(x-1,y+4,8,3,'#c4e4d6');rect(x+10,y+4,7,3,'#c4e4d6')}rect(x+5,y+14,2,5,'#716146');rect(x+9,y+14,2,5,'#716146');rect(x+11,y+7,4,2,'#e8c86b')}
if(state.attack>0){let ax=x+(player.face===1?13:-13);rect(ax,y+8,5,3,'#f1d877');rect(ax+2,y+4,2,11,'#f3edc8');rect(ax+4,y+7,3,3,'#fff3c7')}ctx.restore()}

function draw(){ctx.save();if(state.shake>0)ctx.translate((rnd(state.time*91)-.5)*3,(rnd(state.time*113)-.5)*2);drawSky();ctx.save();ctx.translate(-state.camera,0);drawGround();ctx.restore();drawProps();drawCollectibles();for(const e of enemies)drawEnemy(e);for(const p of state.particles){rect(p.x-state.camera,p.y,3,3,p.c)}drawPlayer();if(state.started&&!state.won){let zone=barriers.find(b=>!b.broken&&Math.abs(player.x-b.x)<75);if(zone){ctx.fillStyle='#efe4bc';ctx.font='7px monospace';ctx.fillText(zone.label,Math.max(4,zone.x-state.camera-20),zone.y-7)}if(player.x>exit.x&&state.seeds<3){ctx.fillStyle='#f2dfa9';ctx.font='7px monospace';ctx.fillText(`NEED ${3-state.seeds} MORE SPIRIT SEED${state.seeds===2?'':'S'}`,W-160,160)}}ctx.restore()}
let last=performance.now();function loop(now){let dt=Math.min(.033,(now-last)/1000);last=now;update(dt);draw();requestAnimationFrame(loop)}requestAnimationFrame(loop);
for(const btn of document.querySelectorAll('[data-key]')){let key=btn.dataset.key,code=key==='ArrowLeft'?'ArrowLeft':key==='ArrowRight'?'ArrowRight':key==='Space'?'Space':'ShiftLeft';const down=e=>{e.preventDefault();keys.add(code);if(code==='Space')player.jumpBuffer=.14;if(code==='ShiftLeft')act()};const up=e=>{e.preventDefault();keys.delete(code)};btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',up);btn.addEventListener('pointerleave',up);btn.addEventListener('pointercancel',up)}for(const btn of document.querySelectorAll('[data-form]'))btn.addEventListener('click',()=>setForm(Number(btn.dataset.form)));
document.addEventListener('visibilitychange',()=>{if(document.hidden)keys.clear()});
