(()=>{'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
const W=480,H=270,worldW=3400,keys=new Set(),ui={overlay:document.getElementById('overlay'),health:document.getElementById('health'),seeds:document.getElementById('seedCount'),form:document.getElementById('formName'),hint:document.getElementById('hint'),toast:document.getElementById('toast')};
const forms=['druid','bear','boar','goat','eagle'],colors={druid:'#62a879',bear:'#b78354',boar:'#dd8b62',goat:'#e0d19a',eagle:'#82c5d0'};
let state={started:false,won:false,time:0,camera:0,toastTimer:0,checkpoint:0,seeds:0,health:3,form:0,attack:0,attackCd:0,particles:[],shake:0};
