const barriers=[{x:560,y:184,w:28,h:38,type:'stone',broken:false,label:'Bear form breaks stone'},{x:930,y:194,w:34,h:28,type:'roots',broken:false,label:'Boar charge tears roots'},{x:1515,y:187,w:28,h:35,type:'stone',broken:false,label:'Bear form breaks stone'},{x:1865,y:190,w:38,h:32,type:'roots',broken:false,label:'Boar charge tears roots'},{x:2750,y:185,w:30,h:37,type:'stone',broken:false,label:'Bear form breaks stone'}];
