const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
function toast(s){ui.toast.textContent=s;ui.toast.classList.add('show');state.toastTimer=2.2}
function start(){if(state.won){location.reload();return}state.started=true;ui.overlay.classList.add('hidden');toast('The grove remembers you.')}
document.getElementById('start').addEventListener('click',start);
window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' ','Shift','Enter'].includes(e.key))e.preventDefault();keys.add(e.code);if(!state.started&&e.code==='Enter')start();if(e.code==='Escape'&&state.started){state.started=false;ui.overlay.classList.remove('hidden')}if(state.started&&!state.won){if(e.code==='Digit1')setForm(1);if(e.code==='Digit2')setForm(2);if(e.code==='Digit3')setForm(3);if(e.code==='Digit4')setForm(4);if(e.code==='KeyQ')setForm((state.form+1)%5);if(e.code==='Space'||e.code==='ArrowUp'||e.code==='KeyW')player.jumpBuffer=.14;if(e.code==='ShiftLeft'||e.code==='ShiftRight'||e.code==='KeyX')act()}});
window.addEventListener('keyup',e=>keys.delete(e.code));
function setForm(n){if(n<1||n>4)return;state.form=n;ui.form.textContent=['DRUID','BEAR','BOAR','GOAT','EAGLE'][n];toast(['','BEAR · MIGHTY BREAKER','BOAR · ROOT-RUNNER','GOAT · CLIFF LEAPER','EAGLE · SKY GLIDER'][n])}
function act(){if(state.attackCd>0)return;state.attack=.25;state.attackCd=.36;if(state.form===2){player.vx=player.face*5.2;player.vy=Math.min(player.vy,0);state.shake=.1}else if(state.form===1)player.vx=player.face*2.7;else if(state.form===3&&player.onGround){player.vy=-4.5;player.onGround=false}else if(state.form===4){player.vy=-2.4;player.flap=.65}else player.vx=player.face*2.4}
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}function rnd(n){let x=Math.sin(n*127.1+4.3)*43758.5453;return x-Math.floor(x)}function overlapping(a,b){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y}function solids(){return platforms.concat(barriers.filter(b=>!b.broken))}
function moveAxis(axis,delta){if(!delta)return;player[axis]+=delta;for(const s of solids())if(overlapping(player,s)){if(axis==='x'){if(delta>0)player.x=s.x-player.w;else player.x=s.x+s.w;player.vx=0}else if(delta>0){player.y=s.y-player.h;player.onGround=true;player.vy=0}else{player.y=s.y;player.vy=0}}}
function damage(){if(player.invuln>0)return;state.health--;player.invuln=1.2;player.vy=-3;player.vx=-player.face*2;toast(state.health?'The thorns bite!':'The grove lends you another breath.');if(state.health<=0){state.health=3;player.x=checkpoints[state.checkpoint].x;player.y=checkpoints[state.checkpoint].y;ui.health.textContent='♥ ♥ ♥';state.seeds=Math.max(0,state.seeds-1);ui.seeds.textContent=`✦ ${state.seeds} / 3`}else ui.health.textContent='♥ '.repeat(state.health)+'♡ '.repeat(3-state.health)}

