function update(dt){S.time+=dt;if(S.timer>0){S.timer-=dt;if(S.timer<=0)ui.toast.classList.remove('show')}if(S.shake>0)S.shake-=dt;if(!S.started)return;S.cool=Math.max(0,S.cool-dt);S.attack=Math.max(0,S.attack-dt);p.invuln=Math.max(0,p.invuln-dt);p.buffer=Math.max(0,p.buffer-dt);const left=keys.has('ArrowLeft')||keys.has('KeyA'),right=keys.has('ArrowRight')||keys.has('KeyD'),dir=(right?1:0)-(left?1:0);if(dir){p.face=dir;const speed=[1.55,1.15,1.8,1.45,1.5][S.form];p.vx+=dir*(p.ground?.42:.2);p.vx=clamp(p.vx,-speed,speed)}else p.vx*=p.ground?.72:.94;if(Math.abs(p.vx)<.04)p.vx=0;if(p.ground)p.coyote=.11;else p.coyote=Math.max(0,p.coyote-dt);if(p.buffer>0&&p.coyote>0){p.vy=S.form===3?-7.7:-5.2;p.ground=false;p.coyote=0;p.buffer=0}if(S.form===4&&p.flap>0&&keys.has('Space')){p.vy=Math.max(p.vy,-2.5);p.flap=Math.max(0,p.flap-dt)}p.vy=Math.min(6.5,p.vy+(S.form===4?.18:.32));p.ground=false;move('x',p.vx);move('y',p.vy);p.x=clamp(p.x,0,worldW-p.w);if(p.y>H+30){damage();p.x=checks[S.checkpoint].x;p.y=checks[S.checkpoint].y;p.vx=p.vy=0}for(let i=0;i<mobs.length;i++){const m=mobs[i];if(m.hp<=0)continue;m.x+=m.d*.45;if(m.x<m.lo||m.x>m.hi)m.d*=-1;const box={x:m.x,y:210,w:15,h:12};if(hit(p,box)){if(S.attack>0||S.form===1&&Math.abs(p.vx)>1.5){m.hp=0;S.parts.push({x:m.x,y:203,vx:0,vy:-2,t:.45,c:'#e6c576'})}else damage()} }for(let i=0;i<seeds.length;i++){const s=seeds[i];if(s.got)continue;if(Math.abs((p.x+p.w/2)-s.x)<13&&Math.abs((p.y+p.h/2)-s.y)<19){s.got=true;S.seeds++;ui.seeds.textContent=`✦ ${S.seeds} / 3`;toast('Spirit seed gathered · the grove stirs!');S.health=Math.min(3,S.health+1);ui.health.textContent='♥ '.repeat(S.health)+'♡ '.repeat(3-S.health)}}for(let i=0;i<checks.length;i++){const c=checks[i];if(Math.abs(p.x-c.x)<15&&S.checkpoint<i){S.checkpoint=i;toast('Waystone awakened · safe travels.')}}for(const b of barriers){if(b.broken||!hit(p,b))continue;const can=(b.type==='stone'&&S.form===1)||(b.type==='roots'&&S.form===2&&Math.abs(p.vx)>2.5);if(can){b.broken=true;S.parts.push({x:b.x,y:b.y,vx:0,vy:-1,t:.5,c:b.type==='stone'?'#9c9b83':'#8c6245'});toast(b.label+' · cleared!')}else{if(p.x<p.previousX+2)p.x=b.x-p.w;else p.x=b.x+b.w;p.vx=0}}p.previousX=p.x;for(const q of S.parts){q.t-=dt;q.vy+=.12;q.x+=q.vx;q.y+=q.vy}S.parts=S.parts.filter(q=>q.t>0);S.camera=clamp(p.x-190,0,worldW-W);if(p.x>exit&&S.seeds>=3){S.won=true;S.started=false;ui.overlay.classList.remove('hidden');ui.overlay.querySelector('.eyebrow').textContent='THE FOURFOLD GROVE IS WHOLE';ui.overlay.querySelector('h1').textContent='WILDROOT';ui.overlay.querySelector('.card p').textContent='The spirit seeds bloom, and the old forest sings again. You brought the grove home.';$('start').textContent='PLAY AGAIN'}}
